mapper.select:
SELECT FROM overtime_requests r JOIN users u ON u.id = r.user_id LEFT JOIN teams t ON t.id = u.team_id WHERE (#{userId} IS NULL OR r.user_id = #{userId})
AND r.user_id IN #{uid}
AND (#{from} IS NULL OR r.work_date >= #{from}) AND (#{to} IS NULL OR r.work_date <= #{to}) ORDER BY r.work_date DESC, r.start_at DESC, r.id DESC

mapper.update:
UPDATE overtime_requests
SET status = #{status}, decided_by = #{decidedBy}, rejected_reason = #{rejectedReason}
WHERE id = #{id}

mapper.select:
SELECT 
FROM overtime_requests r
JOIN users u ON u.id = r.user_id
LEFT JOIN teams t ON t.id = u.team_id
WHERE r.user_id = #{userId}
  AND r.status IN ('PENDING', 'APPROVED')
  AND r.work_date >= #{from}
  AND r.work_date <= #{to}
ORDER BY r.start_at
